/**
 * Shadow-docket data access — the precedent corpus behind
 * `edict_query_precedent`, `edict_case_status` and `edict_explain_ruling`.
 *
 * Reads (read-only) from `apps/shadow-docket`:
 * - `cases/<slug>/case.json`        — committed CaseObject (always present);
 * - `cases/<slug>/groundtruth.json` — expected outcome + rationale + tags;
 * - `cases/<slug>/evidence/*`       — sealed evidence plaintexts (uri-relative);
 * - `reports/verdicts/<caseId>.json`, `reports/report.json`,
 *   `reports/archive/<caseId>/reasoning.json` — GENERATED by a docket run and
 *   may be absent; every reader here degrades gracefully without them.
 *
 * Root resolution: `EDICT_DOCKET_DIR` env override, else the sibling
 * `apps/shadow-docket` of this package.
 *
 * All reads are hardened (mirroring apps/console/src/docket.ts): uri/id
 * allowlists + realpath containment inside the docket root / case dir, and
 * evidence plaintexts are sha256-verified against their commitments —
 * mismatches carry an explicit 'integrity_failed' marker, never silently
 * included.
 */

import { existsSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { CaseObject, Outcome, VerdictObject } from '@edict/core';
import { sha256Hex } from '@edict/evidence';
import { EVIDENCE_URI_RE, SLUG_RE, readFileContained, readJsonContained } from './safeRead.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** groundtruth.json shape (tolerant — fields may be missing on future cases). */
export interface Groundtruth {
  caseId?: string;
  title?: string;
  expected?: unknown;
  acceptableAlternatives?: unknown[];
  rationale?: string;
  difficulty?: string;
  tags?: string[];
  historicalDivergence?: string;
}

/** One per-case entry of reports/report.json `results`. */
export interface ReportResult {
  caseId?: string;
  agreed?: boolean;
  final?: boolean;
  escalated?: boolean;
  majority?: string;
  swapFlipRate?: number;
  [k: string]: unknown;
}

export interface DocketCase {
  /** Directory name, e.g. "c01-minerals-attestation". */
  slug: string;
  caseDir: string;
  caseObj: CaseObject;
  groundtruth: Groundtruth;
}

/** A commitment whose on-disk bytes did NOT hash to the committed sha256. */
export interface EvidenceIntegrityFailure {
  sha256: string;
  uri: string;
  status: 'integrity_failed';
}

export interface EvidenceLoad {
  /** Verified plaintexts keyed by committed sha256 (hash-checked on load). */
  plaintext: Record<string, string>;
  /** Explicit markers for tampered files — excluded from `plaintext`. */
  integrityFailed: EvidenceIntegrityFailure[];
}

/** Outcome of reading one evidence commitment's local file. */
type EvidenceFileRead =
  | { status: 'ok'; text: string }
  | { status: 'sealed' } // no readable local file (non-local uri, missing, or containment-rejected)
  | { status: 'integrity_failed' }; // bytes read but sha256 does not match the commitment

export interface PrecedentHit {
  caseId: string;
  ref: string;
  title: string;
  /** The local verdict's ruling when a docket run exists, else the groundtruth expectation. */
  ruling: Outcome | unknown;
  rulingSource: 'local_verdict' | 'groundtruth_expected';
  final?: boolean;
  holding: string;
  snippet: string;
  tags: string[];
  difficulty?: string;
  score: number;
}

// ---------------------------------------------------------------------------
// Store
// ---------------------------------------------------------------------------

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Default root: <this package>/../shadow-docket (apps/ sibling). */
export function resolveDocketRoot(): string {
  const env = process.env['EDICT_DOCKET_DIR'];
  if (env !== undefined && env.length > 0) return env;
  const here = dirname(fileURLToPath(import.meta.url)); // apps/mcp-server/dist
  return join(here, '..', '..', 'shadow-docket');
}

export class DocketStore {
  readonly root: string;
  private cases: DocketCase[] | undefined;

  constructor(root: string = resolveDocketRoot()) {
    this.root = root;
  }

  /** All loadable cases (case.json + groundtruth.json). Unreadable dirs are skipped. */
  loadCases(): DocketCase[] {
    if (this.cases !== undefined) return this.cases;
    const casesDir = join(this.root, 'cases');
    const out: DocketCase[] = [];
    let slugs: string[] = [];
    try {
      slugs = readdirSync(casesDir, { withFileTypes: true })
        .filter((d) => d.isDirectory() && SLUG_RE.test(d.name))
        .map((d) => d.name)
        .sort();
    } catch {
      slugs = [];
    }
    for (const slug of slugs) {
      const caseDir = join(casesDir, slug);
      const caseObj = readJsonContained(this.root, join(caseDir, 'case.json')) as CaseObject | undefined;
      if (caseObj === undefined || typeof caseObj.caseId !== 'string') continue;
      const groundtruth = (readJsonContained(this.root, join(caseDir, 'groundtruth.json')) ?? {}) as Groundtruth;
      out.push({ slug, caseDir, caseObj, groundtruth });
    }
    this.cases = out;
    return out;
  }

  /** Resolve by caseId (uuid) or by slug (directory name). */
  findCase(ref: string): DocketCase | undefined {
    const needle = ref.trim().toLowerCase();
    return this.loadCases().find((c) => c.caseObj.caseId.toLowerCase() === needle || c.slug.toLowerCase() === needle);
  }

  /** Local verdict from reports/verdicts/<caseId>.json, when a docket run exists. */
  verdict(caseId: string): VerdictObject | undefined {
    if (!SLUG_RE.test(caseId)) return undefined; // no separators/dot-prefix → no traversal
    const v = readJsonContained(this.root, join(this.root, 'reports', 'verdicts', `${caseId}.json`));
    return isRecord(v) && typeof v['caseId'] === 'string' ? (v as unknown as VerdictObject) : undefined;
  }

  /** Per-case result from reports/report.json, when a docket run exists. */
  reportResult(caseId: string): ReportResult | undefined {
    const report = readJsonContained(this.root, join(this.root, 'reports', 'report.json')) as
      | { results?: ReportResult[] }
      | undefined;
    return report?.results?.find((r) => r.caseId === caseId);
  }

  /** Archived structured reasoning document, when a docket run exists. */
  reasoning(caseId: string): Record<string, unknown> | undefined {
    if (!SLUG_RE.test(caseId)) return undefined; // no separators/dot-prefix → no traversal
    const r = readJsonContained(this.root, join(this.root, 'reports', 'archive', caseId, 'reasoning.json'));
    return isRecord(r) ? r : undefined;
  }

  /** True when generated reports are present locally. */
  hasReports(): boolean {
    return existsSync(join(this.root, 'reports', 'verdicts'));
  }

  /**
   * Load a case's local evidence files, hardened like the console reader:
   * - only `evidence/<file>` case-dir-relative uris are readable — URL schemes
   *   (vault://, ipfs://), absolute paths and `..` segments are rejected by
   *   the allowlist pattern and stay sealed;
   * - the file must additionally realpath-resolve INSIDE the case directory,
   *   so a symlink planted under evidence/ cannot read outside files;
   * - loaded bytes must sha256 to the commitment; mismatches are EXCLUDED
   *   from `plaintext` and reported in `integrityFailed` with an explicit
   *   'integrity_failed' marker (never silently included).
   */
  loadEvidence(c: DocketCase): EvidenceLoad {
    const plaintext: Record<string, string> = {};
    const integrityFailed: EvidenceIntegrityFailure[] = [];
    for (const commitment of c.caseObj.evidence) {
      if (commitment.uri === undefined || plaintext[commitment.sha256] !== undefined) continue;
      const read = this.readEvidenceFile(c.caseDir, commitment.uri, commitment.sha256);
      if (read.status === 'ok') {
        plaintext[commitment.sha256] = read.text;
      } else if (read.status === 'integrity_failed') {
        integrityFailed.push({ sha256: commitment.sha256, uri: commitment.uri, status: 'integrity_failed' });
      }
      /* 'sealed' → stays sealed (renders as [sealed] downstream) */
    }
    return { plaintext, integrityFailed };
  }

  /**
   * Verified evidence plaintexts for a case, keyed by committed sha256 —
   * the `plaintext` half of {@link loadEvidence}.
   */
  evidencePlaintext(c: DocketCase): Record<string, string> {
    return this.loadEvidence(c).plaintext;
  }

  /** Containment-checked, hash-verified read of one commitment's local file. */
  private readEvidenceFile(caseDir: string, uri: string, sha256: string): EvidenceFileRead {
    if (!EVIDENCE_URI_RE.test(uri)) return { status: 'sealed' };
    const text = readFileContained(caseDir, join(caseDir, uri));
    if (text === undefined) return { status: 'sealed' };
    if (sha256Hex(text) !== sha256) return { status: 'integrity_failed' };
    return { status: 'ok', text };
  }

  // -------------------------------------------------------------------------
  // Precedent search
  // -------------------------------------------------------------------------

  /**
   * Keyword search over cases + groundtruth rationales + (when present) local
   * verdicts. `tags` filters to cases carrying EVERY requested tag.
   */
  queryPrecedent(query: string, tags?: string[], limit = 5): PrecedentHit[] {
    const tokens = tokenize(query);
    const wantTags = (tags ?? []).map((t) => t.trim().toLowerCase()).filter((t) => t.length > 0);
    const hits: PrecedentHit[] = [];

    for (const c of this.loadCases()) {
      const gt = c.groundtruth;
      const caseTags = (gt.tags ?? []).map((t) => t.toLowerCase());
      if (wantTags.length > 0 && !wantTags.every((t) => caseTags.includes(t))) continue;

      const mandateDescription = this.mandateDescription(c);
      const fields: Array<{ text: string; weight: number }> = [
        { text: gt.title ?? '', weight: 4 },
        { text: caseTags.join(' ').replace(/_/g, ' '), weight: 4 },
        { text: c.slug.replace(/-/g, ' '), weight: 3 },
        { text: gt.rationale ?? '', weight: 2 },
        { text: mandateDescription, weight: 2 },
        { text: gt.historicalDivergence ?? '', weight: 1 },
        { text: `${c.caseObj.caseType} ${c.caseObj.decisionSpace.kind}`, weight: 1 },
      ];

      let score = 0;
      for (const token of tokens) {
        for (const f of fields) {
          if (f.text.toLowerCase().includes(token)) score += f.weight;
        }
      }
      // A pure tag query (no free-text hits) still surfaces the tagged cases.
      if (score === 0 && !(wantTags.length > 0 && tokens.length === 0)) continue;

      const verdict = this.verdict(c.caseObj.caseId);
      const rationale = gt.rationale ?? '';
      hits.push({
        caseId: c.caseObj.caseId,
        ref: c.slug,
        title: gt.title ?? c.slug,
        ruling: verdict?.ruling ?? gt.expected,
        rulingSource: verdict !== undefined ? 'local_verdict' : 'groundtruth_expected',
        ...(verdict !== undefined ? { final: verdict.final } : {}),
        holding: firstSentence(rationale),
        snippet: snippetFor(tokens, [rationale, mandateDescription, gt.historicalDivergence ?? '']),
        tags: gt.tags ?? [],
        ...(gt.difficulty !== undefined ? { difficulty: gt.difficulty } : {}),
        score,
      });
    }

    hits.sort((a, b) => b.score - a.score || a.ref.localeCompare(b.ref));
    return hits.slice(0, limit);
  }

  /** The order-mandate description for a case, when its verified plaintext is readable JSON. */
  private mandateDescription(c: DocketCase): string {
    const commitment = c.caseObj.evidence.find((e) => e.kind === 'order_mandate');
    if (commitment?.uri === undefined) return '';
    const read = this.readEvidenceFile(c.caseDir, commitment.uri, commitment.sha256);
    if (read.status !== 'ok') return '';
    try {
      const om = JSON.parse(read.text) as { description?: unknown };
      return typeof om.description === 'string' ? om.description : '';
    } catch {
      return '';
    }
  }
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'case', 'cases', 'did', 'do', 'for', 'from',
  'has', 'have', 'in', 'is', 'it', 'of', 'on', 'or', 'that', 'the', 'this', 'to', 'was', 'were',
  'what', 'when', 'where', 'which', 'who', 'why', 'with',
]);

export function tokenize(query: string): string[] {
  return [...new Set(
    query
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((t) => t.length >= 2 && !STOPWORDS.has(t)),
  )];
}

function firstSentence(text: string): string {
  const t = text.trim();
  if (t.length === 0) return '';
  const dot = t.search(/(?<=[.!?])\s/);
  const s = dot === -1 ? t : t.slice(0, dot);
  return s.length > 220 ? `${s.slice(0, 217)}…` : s;
}

/** ±window chars of context around the first token match across candidate texts. */
function snippetFor(tokens: string[], candidates: string[], window = 110): string {
  for (const text of candidates) {
    const lower = text.toLowerCase();
    for (const token of tokens) {
      const at = lower.indexOf(token);
      if (at === -1) continue;
      const start = Math.max(0, at - window);
      const end = Math.min(text.length, at + token.length + window);
      const prefix = start > 0 ? '…' : '';
      const suffix = end < text.length ? '…' : '';
      return `${prefix}${text.slice(start, end).replace(/\s+/g, ' ').trim()}${suffix}`;
    }
  }
  return firstSentence(candidates[0] ?? '');
}
